describe("运行期那一句与那一个值", () => {
  it("逐格对引擎", async () => {
    let bad = 0;
    let firstBad = "";
    for (const [label, call, want] of CELLS) {
      let got = "";
      try {
        got = "V:" + show(call());
      } catch (e) {
        got = "E:" + (e instanceof Error ? e.message : String(e));
      }
      if (got !== want) {
        bad++;
        if (firstBad === "") firstBad = `${label}：期望 ${want}，实得 ${got}`;
      }
    }
    eq("399", "不合数", bad + (bad > 0 ? ` 首格[${firstBad}]` : ""), 0);
  });
});
